INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64811817', 64811817, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analis Inovasi Pendanaan dan Kerja Sama Internasional, Kajian Inovasi Pendanaan, Pembiayaan, dan Kerja Sama Internasional dalam Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi pada Sektor Pengolahan Sawit', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 25000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'kegiatan analitis dan teknis yang memerlukan keahlian khusus, antara lain dalam penyusunan dan pengelolaan data, analisis data kuantitatif, serta analisis peran dan sinergi Pentahelix yang melibatkan pemerintah, akademisi, dunia usaha, komunitas/petani, dan mitra internasional, serta koordinasi dengan mitra internasional, yang dilaksanakan di luar pelaksanaan tugas dan fungsi ASN guna mendukung perumusan rekomendasi kebijakan pendanaan dan pembiayaan yang komprehensif, berbasis bukti', 'Konsultan Analis Inovasi Pendanaan dan Kerja Sama Internasional bertanggung jawab terhadap pelaksanaan Kajian Inovasi Pendanaan, Pembiayaan, dan Kerja Sama Internasional dalam Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi pada Sektor Pengolahan Sawit, antara lain: 1. Pengawalan penyiapan dan penandatanganan MoU Bappenas–CSES Mengawal proses penyiapan substansi dan penandatanganan MoU agar kerja sama berjalan selaras dengan prioritas pembangunan nasional dan agenda ekonomi hijau. 2. Analisis peluang kerja sama Indonesia–Tiongkok Mengkaji peluang dan manfaat strategis kerja sama Indonesia–Tiongkok dalam pengembangan pengolahan sawit rendah emisi dan perdagangan karbon. 3. Kajian keterkaitan kerja sama dengan pengembangan PaMER Menilai bagaimana kerja sama internasional dapat mendukung pengembangan dan implementasi mini-plant PaMER di Cikidang, Sukabumi. 4. Analisis peran dan sinergi Pentahelix Mengidentifikasi peran dan kerja sama antara pemerintah, akademisi, dunia usaha, komunitas petani, dan mitra internasional agar program berjalan terintegrasi. 5. Penyusunan rekomendasi kebijakan dan tindak lanjut Menyusun rekomendasi dan langkah lanjutan yang dapat segera dilaksanakan untuk mendukung implementasi kerja sama dan pengembangan PaMER.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1781939);
