INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64811582', 64811582, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Model Analisis Pemerataan Pembangunan Wilayah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 34000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Kegiatan ini dimaksudkan untuk mendukung Staf Ahli Menteri Bidang Pemerataan Pembangunan Regional dalam memperkuat kualitas perumusan kebijakan dan desain intervensi pemerataan pembangunan wilayah yang selaras dengan arah kebijakan nasional.', 'Ruang lingkup pekerjaan difokuskan pada penyusunan kerangka analisis dan model pemerataan pembangunan wilayah yang bersifat konseptual, metodologis, dan operasional, meliputi: i. Menyusun kerangka konseptual model pemerataan pembangunan wilayah, yang mengintegrasikan dimensi struktur ekonomi, ketimpangan regional, kondisi sosial-ekonomi, konektivitas, dan kelembagaan pusat-daerah. ii. Mengkaji dan merumuskan variabel, indikator, serta pendekatan analisis yang relevan untuk membaca ketimpangan dan dinamika pembangunan wilayah secara komprehensif dan terukur. iii. Menganalisis keterkaitan antar-dimensi dalam pemerataan pembangunan wilayah, termasuk hubungan antara struktur ekonomi, pusat pertumbuhan, kerentanan sosial, dan integrasi wilayah. iv. Menyusun kerangka tahapan analisis (analytical roadmap) yang akan digunakan sebagai panduan pelaksanaan kajian pemerataan pembangunan wilayah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1782569);
