INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64811498', 64811498, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Model Analisis Statistik Pembangunan Wilayah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99960000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Kegiatan ini dimaksudkan untuk mendukung Unit Staf Ahli Menteri Bidang Pemerataan Pembangunan Regional dalam menyusun model analisis statistik pembangunan wilayah sebagai kerangka metodologis yang menjadi acuan bersama dalam pelaksanaan kajian dan analisis pemerataan pembangunan wilayah.', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Model Analisis Statistik Pembangunan Wilayah meliputi kegiatan teknis dan analitis untuk menghasilkan model statistik dan perangkat analisis pembangunan wilayah, yang digunakan sebagai bahan pendukung teknis oleh Unit Staf Ahli Menteri Bidang Pemerataan Pembangunan Regional, dengan rincian sebagai berikut: 1. Menyusun arsitektur data dan kerangka kerja analisis statistik pembangunan wilayah, termasuk penentuan struktur dataset, klasifikasi wilayah, periode analisis, serta definisi operasional indikator yang digunakan dalam analisis ketimpangan wilayah. 2. Melakukan pengolahan dan analisis statistik deskriptif terhadap indikator pembangunan wilayah, untuk mengidentifikasi pola sebaran, variasi, dan ketimpangan pembangunan antarwilayah dan intrawilayah secara kuantitatif. 3. Mengembangkan model statistik analitis untuk mengukur dan membandingkan tingkat ketimpangan pembangunan wilayah, termasuk pemilihan metode statistik yang relevan dan penjelasan asumsi serta keterbatasan model. 4. Menyusun kerangka analisis spasial berbasis data statistik, guna memetakan keterkaitan antarindikator pembangunan dan perbedaan karakteristik wilayah dalam bentuk visual dan analisis kewilayahan. 5. Mengembangkan skema proyeksi (forecasting) terbatas berbasis model statistik, sebagai alat bantu analitis untuk membaca kecenderungan perubahan ketimpangan pembangunan wilayah dalam horizon waktu tertentu. 6. Menyusun bahan teknis analitis dan visualisasi hasil model, termasuk tabel, grafik, dan prototipe dashboard analitis, sebagai bahan pendukung pembahasan internal dan perumusan rekomendasi kebijakan pemerataan pembangunan wilayah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1782599);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64851559', 64851559, 'analyze_legacy', 'Kab. Pekalongan', 'kabkota', 'Dinas Pendidikan dan Kebudayaan', 'Pengadaan Air Conditioning (AC) Dinas Pendidikan dan Kebudayaan Kabupaten Pekalongan', 'Barang', 'Pengadaan Langsung', 'Jawa Tengah, Pekalongan (Kab.)', 18588000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Pengadaan Air Conditioning (AC) Dinas Pendidikan dan Kebudayaan Kabupaten Pekalongan', 'Pengadaan Air Conditioning (AC) Dinas Pendidikan dan Kebudayaan Kabupaten Pekalongan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1782600);
