INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64811755', 64811755, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analis Inovasi Pendanaan Pembangunan Kewilayahan Kajian Inovasi Pendanaan dan Pembiayaan Pembangunan Kewilayahan untuk Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi pada Pengolahan Sawit', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 25000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'kegiatan analitis dan teknis yang memerlukan keahlian khusus dalam pengolahan dan analisis data pembangunan dan/atau pengolahan serta analisis data menggunakan perangkat statistik, analisis pembangunan wilayah/daerah dan/atau pembiayaan serta pendanaan pembangunan, serta manajemen tata kelola dan manajemen risiko. Pelaksanaan kegiatan ini juga mencakup koordinasi lintas pemangku kepentingan, dan dilaksanakan di luar pelaksanaan tugas dan fungsi ASN, guna mendukung penyusunan rekomendasi kebijakan pendanaan dan pembiayaan pembangunan kewilayahan yang komprehensif, berbasis bukti', 'Konsultan Analis Inovasi Pendanaan Pembangunan Kewilayahan bertanggung jawab terhadap pelaksanaan Kajian Inovasi Pendanaan dan Pembiayaan Pembangunan Kewilayahan untuk Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi pada Pengolahan Sawit, antara lain: a) Mengawal dan memfasilitasi proses penyiapan penandatanganan MoU antara Kementerian PPN/Bappenas dan Chinese Society for Environmental Sciences (CSES), termasuk sinkronisasi substansi kerja sama, ruang lingkup kegiatan, pembagian peran, dan keselarasan dengan prioritas RPJMN 2025–2029. b) Mengawal koordinasi lintas pemangku kepentingan (Bappenas, CSES, kementerian/lembaga terkait, pemerintah daerah, dan mitra teknis) untuk memastikan kesiapan kelembagaan dan keberlanjutan pelaksanaan kerja sama Indonesia–Tiongkok di bidang pengolahan sawit rendah emisi dan inovasi pendanaan. c) Mengawal progres pengembangan teknologi PaMER oleh Universitas Indonesia, khususnya pada tahap perencanaan pembangunan pabrik mini-plant di Cikidang, Kabupaten Sukabumi, agar selaras dengan tujuan pembuktian teknologi rendah emisi dan kebutuhan pengembangan mekanisme perdagangan karbon. d) Menganalisis kesiapan kewilayahan lokasi Cikidang–Sukabumi sebagai pilot area, mencakup dukungan pemerintah daerah, kesiapan lahan dan infrastruktur pendukung, serta keterkaitannya dengan rantai nilai sawit dan pembangunan ekonomi lokal. e) Mengintegrasikan aspek inovasi pendanaan kewilayahan dalam pengembangan mini-plant PaMER, termasuk potensi pembiayaan berbasis kinerja penurunan emisi, perdagangan karbon, blended finance, dan peran pembiayaan publik–swasta di tingkat daerah. f) Memfasilitasi keterkaitan antara pengembangan teknologi, kerja sama internasional, dan model pendanaan kewilayahan, agar mini-plant PaMER tidak berdiri sebagai proyek teknis semata, tetapi menjadi bagian dari model pembangunan rendah emisi yang replikatif. g) Menyusun catatan kemajuan (progress brief) dan rekomendasi tindak lanjut yang bersifat operasional bagi Bappenas, untuk mendukung kelancaran penandatanganan MoU, implementasi awal kerja sama, dan penguatan kesiapan tahap berikutnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1783095);
