INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64811639', 64811639, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analis Inovasi Pendanaan dan Pembiayaan Pembangunan Energi Terbarukan kegiatan Kajian Inovasi Pendanaan dan Pembiayaan Pembangunan Energi Terbarukan untuk Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi di Sektor Persampahan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 55000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Dalam pelaksanaan kegiatan Kajian Inovasi Pendanaan dan Pembiayaan Pembangunan Energi Terbarukan untuk Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi di Sektor Persampahan, konsultan yang dikontrak berkedudukan sebagai Konsultan Analis Inovasi Pendanaan dan Pembiayaan Pembangunan Energi Terbarukan.', 'Konsultan Analis Inovasi Pendanaan dan Pembiayaan Pembangunan Energi Terbarukan bertanggung jawab terhadap pelaksanaan Kajian Inovasi Pendanaan dan Pembiayaan Pembangunan Energi Terbarukan untuk Mendukung Pembangunan Ramah Lingkungan dan Rendah Emisi di Sektor Persampahan, antara lain: a) Mengumpulkan data kebijakan dan skema pendanaan energi terbarukan yang terkait dengan pengolahan sampah. b) Mengumpulkan dan menelaah data kebijakan serta skema pendanaan energi terbarukan yang terkait dengan pengolahan sampah, termasuk pengembangan PLTSa dalam kerangka KPBU persampahan. c) Menganalisis potensi energi terbarukan dari pengolahan sampah untuk memperkuat struktur pendapatan proyek, dengan memperhatikan karakteristik teknis dan finansial proyek PLTSa. d) Menganalisis struktur pendapatan proyek, termasuk kejelasan dan keberlanjutan tarif layanan, tipping fee, serta pendapatan dari penjualan listrik pada proyek PLTSa berbasis persampahan. e) Menganalisis kesiapan pembiayaan (financing readiness) proyek energi terbarukan berbasis persampahan, termasuk kepastian kontrak, kelayakan pendapatan, dan dukungan kebijakan, dengan studi kasus PLTSa Nambo dan PLTSa Legok Nangka. f) Menganalisis pembagian risiko proyek PLTSa, termasuk risiko teknologi, pasokan sampah, pendapatan, dan kebijakan, untuk memastikan pembagian risiko yang jelas dan proporsional antara pemerintah dan badan usaha. g) Mengidentifikasi hambatan pembiayaan swasta dan pencapaian financial close pada proyek energi terbarukan persampahan, dengan pembelajaran dari pengalaman penyiapan dan implementasi PLTSa Nambo dan Legok Nangka. h) Menyusun rekomendasi kebijakan dan skema pendanaan energi terbarukan yang operasional dan bankable, dengan mengacu pada praktik terbaik dan pelajaran kebijakan dari proyek PLTSa Nambo dan Legok Nangka, guna mendorong keterlibatan sektor swasta dan percepatan financial close proyek sejenis di masa depan. i) Menyusun rekomendasi kebijakan dan skema pendanaan energi terbarukan berbasis waste to energy yang praktis dan dapat diterapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1784219);
