INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64812272', 64812272, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Balai Besar Perluasan Kesempatan Kerja Bandung Barat', 'Pengadaan Jasa Layanan Internet (periode Februari 2026)', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung Barat (Kab.)', 30000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PAKET', 'Pengadaan jasa layanan internet di kantor BBPKK Bandung Barat selama 1 bulan', 'Spesifikasi Mutu dan pelayanan : 1. Penyedia mampu menyediakan jaringan akses fiber optic dengan bandwidth sebesar 500 Mbps dengan perbandingan upstream dan downstream = 1:1; 2. SLA = 99,9%; 3. Pekerjaan ini menggunakan produksi dalam negeri dengan ketentuan memiliki Tingkat Komponen Dalam negeri (TKDN) + nilai Bobot manfaat Perusahaan (BMP) minimal 40% atau merupakan Produk Dalam Negeri (PDN); 4. Penyediaan dukungan perangkat (access point, router, kabel dan perangkat lain yang dibutuhkan) termasuk perawatannya dan penggantian apabila terjadi kerusakan; 5. Setelah melakukan pemasangan dan instalasi, penyedia harus menyampaikan dokumen meliputi detail instalasi, gambar jaringan, dan IP management kepada user; 6. Penyedia melaporkan performa layanan secara rutin setiap bulan (penggunaan/traffic bandwidth, proses maintenance, penanganan kendala teknis di lapangan); 7. Sistem jaringan bersifat manageable yang dapat diakses oleh user untuk memantau tingkat performa jaringan; 8. Sistem jaringan harus menjamin keamanan jaringan untuk melindungi data dan informasi yang dimiliki user; 9. Penyedia harus kooperatif untuk bekerjasama dengan user untuk keperluan koordinasi, evaluasi yang berkaitan dengan pekerjaan; 10. Menyampaikan SOP terkait penanganan kendala teknis di lapangan yang jelas dan mudah untuk diikuti. 11. Menyampaikan ketersediaan dan informasi redundancy backbone; 12. Melaporkan utilisasi bandwidth yang dapat dilihat secara langsung oleh user atas penggunaannya; 13. Mendapatkanperawatan, dukungan dan pelayanan baik online maupun onsite, termasuk penyediaan teknisi apabila kendala yang terjadimembutuhkan penyelesaian langsung di lapangan; 14. Penyedia menjamin bahwa apabila perangkat pendukung terjadi kerusakan atau tidak dapat berfungsi dengan baik selama jangka waktu tertentu, sebagai garansi penyedia menyediakan perangkat penggantinya tanpa ada biaya tambahan; 15. Setiap bulan penyedia wajib menyampaikan laporan (isi disesuaikan dengan spesifikasi mutu/kualitas) sebagai salah satu kelengkapan dokumen untuk mengajukan pembayaran pekerjaan; 16. Memberikan contact service yang tersedia 24 jam, sistem trouble ticketing dan eskalasi prosedur penanganan masalah yang jelas; 17. Recovery time maksimum 48 (empat puluh delapan) jam setelah kendala disampaikan oleh user; 18. Melakukan rekonfigurasi untuk memastikan ketersediaan dan keandalan performa internet tetap stabil, termasuk yang bersifat insidentil seperti pelaksanaan wawancara penerima bantuan secara online, karena kegiatan tersebut membutuhkan bandwidth yang besar agar dapat disediakan oleh penyedia untuk tambahan bandwidth yang diperlukan; 19. Melakukan transfer knowledge kepada teknisi/pegawai yang diberi tugas berkoordinasi dengan pihak penyedia internet, termasuk panduan pemeliharaan dan cara mengoperasikan perangkat pendukung layanan internet yang disediakan; 20. Penyedia bersama-sama dengan user melakukan test via speedtest setelah selesai proses intalasi untuk menguji kecepatan internet apakah sudah/belum sesuai dengan spesifikasi. Apabila belum sesuai maka penyedia wajib melakukan perbaikan atau upaya lain yang diperlukan agar kecepatan internet memenuhi spesifikasi yang telah ditentukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1784920);
