INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64834928', 64834928, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SEKRETARIAT DPRD', 'Pengadaan Layanan Cloud Computing Dengan GPU untuk Pemrosesan Data dan Kecerdasan Buatan', 'Jasa Konsultansi', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 144690336, 'January 2026', 'APBD', 1, 1, '1 Bulan', 'Menyediakan infrastruktur komputasi berbasis cloud GPU yang andal, fleksibel, dan memiliki kemampuan pemrosesan tinggi guna mendukung kegiatan analisis data serta pengembangan model kecerdasan buatan.', 'Mendukung sistem operasi linux, debian, dan windows base dengan Lokasi data center berada di Indonesia, memiliki layanan dashboard monitoring, memiliki portal akses kedalam layanan cloud, memiliki layanan antar muka yang intuitive dan mudah digunakan dengan spesifikasi teknis sebagai berikut: Computer Solution 2 Instances , masing-masing instances spesifikasinya: 12vCPU, Memory 144 GB, GPU VRAM 24 GB, Storage Solution 512 GB, Jenis Server Virtual PrivateCloud.', 144690336, 'high', 'Pengadaan layanan cloud GPU berkapasitas tinggi untuk analisis data dan pengembangan AI pada lingkungan sekretariat legislatif tampak kurang selaras dengan fungsi administratif umum. Spesifikasi komputasi relatif besar untuk durasi hanya 1 bulan, sehingga seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 1788974);
