INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64878167', 64878167, 'analyze_legacy', 'Mahkamah Agung', 'central', 'BADAN PENGAWASAN MAHKAMAH AGUNG RI', 'Pengadaan Bahan/Souvenir Pameran Kampung Hukum 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 140000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1508 Pcs', 'Pengadaan Bahan/Souvenir Pameran Kampung Hukum 2026 dalam Rangka Laporan Tahunan 2025', '- Smartwatch : Layar 2.0 inci LCD beresolusi 320 × 385 dengan kecerahan hingga 500 nits, membuat tampilan tetap jelas di luar ruangan, Baterai 470 mAh yang tahan hingga ~18 hari pada penggunaan biasa, dan ~12 hari untuk penggunaan berat, Pengisian via magnetic charging cable yang praktis, Mendukung lebih dari 140 mode olahraga, termasuk berjalan, berlari, bersepeda, skipping, dan lainnya, Pelacakan kesehatan 24/7: detak jantung, SpO₂ (oksigen darah), tidur, dan stres, Fitur kesehatan wanita seperti monitoring siklus menstruasi, Bluetooth v5.3 dengan dukungan panggilan suara (dengan mikrofon ENC dan speaker), Kompatibel dengan Android & iOS via aplikasi Mi Fitness (Xiaomi Wear), Bahasa antarmuka termasuk Bahasa Indonesia/Hindi/Inggris. - Payung Lipat : Sablon Custom Logo 2 Sisi - Tumblr : 350ml custom sablon/grafir 2 sisi - Kipas Portable : sticker/garskin - Powerbank : Magsafe magnet 20watt untuk semua jenis handphone - TWS : daya tahan 36 jam, bluetooth 5.3, water resistance ipx 5 - Travel Pouch : Sablon - Buku Agenda : Custom Logo Box dan Buku satu set Pulpen - Speaker Jam : Bluetooth - Powerbank : 10.000 MAh 22 Watt - ID Card Holder : Dengan Tali bisa menyimpan banyak kartu - Tote Bag Belanja : praktis dan mudah dibawah, dengan berbagai warna - Mug : Custom Design - Kipas Manual : Sablon 2 sisi - Set Alat Makan : Sendok, Garpu, Sumpit - emoney : Custom Design - Batik : Lengan Panjang dan Blouse - Booklet : Custom Design - Tote Bag : Canvas Custome - Lanyard ID : Kulit Sintetis Warna', 70000000, 'high', 'Pengadaan souvenir pameran berisi sejumlah barang elektronik konsumtif dan item non-esensial seperti smartwatch, TWS, speaker jam, dan powerbank, yang tampak kurang proporsional untuk kebutuhan pameran/komunikasi publik lembaga peradilan. Komposisi barang cenderung bersifat hadiah/merchandise bernilai tinggi sehingga berindikasi pemborosan anggaran.', NULL, NULL, 3, 1, 1, 1, 1, 1789345);
